from __future__ import annotations

COMPACT_STYLE = "QToolButton, QPushButton { padding: 5px 9px; } QTabBar::tab { padding: 6px 12px; } QHeaderView::section { padding: 5px; font-weight: 600; }"
LIGHT_STYLE = COMPACT_STYLE + " QWidget { background: #f7f9fc; color: #1f2937; } QMainWindow, QGroupBox, QMdiArea { background: #f7f9fc; color: #1f2937; } QGroupBox { border: 1px solid #b8c2d1; border-radius: 5px; margin-top: 8px; padding-top: 8px; font-weight: 600; } QLineEdit, QTextEdit, QTableWidget, QTreeWidget, QComboBox, QSpinBox { background: #ffffff; color: #111827; border: 1px solid #7b8798; selection-background-color: #1d4ed8; selection-color: #ffffff; } QPushButton, QToolButton { background: #e8eef7; color: #172033; border: 1px solid #718096; border-radius: 4px; } QPushButton:hover, QToolButton:hover { background: #d5e2f5; border-color: #1d4ed8; } QPushButton:pressed, QToolButton:pressed { background: #b9cbea; } QPushButton:disabled, QToolButton:disabled { background: #edf0f4; color: #8a94a3; border-color: #c7ced8; } QTabBar::tab { background: #e3eaf4; color: #26364d; border: 1px solid #aab7c8; padding: 6px 12px; } QTabBar::tab:selected { background: #1d4ed8; color: #ffffff; border-color: #173ea5; } QHeaderView::section { background: #dbe5f2; color: #172033; border: 1px solid #9eacbe; } QTreeWidget::item:selected, QTableWidget::item:selected { background: #1d4ed8; color: #ffffff; } QMenu { background: #ffffff; color: #111827; border: 1px solid #7b8798; } QMenu::item:selected { background: #dbeafe; color: #111827; } QToolTip { background: #111827; color: #ffffff; border: 1px solid #4b5563; } QStatusBar { background: #e5eaf2; color: #172033; } QScrollBar:vertical, QScrollBar:horizontal { background: #e9eef5; } QProgressBar { background: #ffffff; color: #111827; border: 1px solid #7b8798; text-align: center; } QProgressBar::chunk { background: #1d4ed8; }"
DARK_STYLE = COMPACT_STYLE + " QWidget { background: #171a21; color: #f3f4f6; } QMainWindow, QGroupBox, QMdiArea { background: #171a21; color: #f3f4f6; } QGroupBox { border: 1px solid #667085; border-radius: 5px; margin-top: 8px; padding-top: 8px; font-weight: 600; } QLineEdit, QTextEdit, QTableWidget, QTreeWidget, QComboBox, QSpinBox { background: #232833; color: #f9fafb; border: 1px solid #8490a3; selection-background-color: #2563eb; selection-color: #ffffff; } QPushButton, QToolButton { background: #2d3748; color: #f9fafb; border: 1px solid #8b98ab; border-radius: 4px; } QPushButton:hover, QToolButton:hover { background: #3b4a62; border-color: #60a5fa; } QPushButton:pressed, QToolButton:pressed { background: #465a78; } QPushButton:disabled, QToolButton:disabled { background: #252b35; color: #7f8a9b; border-color: #4b5563; } QTabBar::tab { background: #2d3748; color: #e5e7eb; border: 1px solid #667085; padding: 6px 12px; } QTabBar::tab:selected { background: #2563eb; color: #ffffff; border-color: #60a5fa; } QHeaderView::section { background: #303b4e; color: #f9fafb; border: 1px solid #6b778b; } QTreeWidget::item:selected, QTableWidget::item:selected { background: #2563eb; color: #ffffff; } QMenu { background: #202631; color: #f9fafb; border: 1px solid #8490a3; } QMenu::item:selected { background: #334e7a; color: #ffffff; } QToolTip { background: #f9fafb; color: #111827; border: 1px solid #9ca3af; } QStatusBar { background: #252c38; color: #f3f4f6; } QScrollBar:vertical, QScrollBar:horizontal { background: #232833; } QProgressBar { background: #232833; color: #f9fafb; border: 1px solid #8490a3; text-align: center; } QProgressBar::chunk { background: #2563eb; }"


def apply_theme(theme: str) -> None:
    from PySide6.QtWidgets import QApplication

    app = QApplication.instance()
    if app is not None:
        app.setStyleSheet(DARK_STYLE if theme == "dark" else LIGHT_STYLE)
